using System;using System.IO;using System.Text;using System.Drawing;using System.Windows.Forms;using System.Threading;using System.Threading.Tasks;using System.Diagnostics;using System.Net;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
internal static class Program {
 internal static string BaseDir,DataDir,BaseUrl;internal static bool Testing;internal static Process OwnedBridge;internal static JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=40*1024*1024};
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);BaseDir=AppDomain.CurrentDomain.BaseDirectory;Testing=args.Length>0&&args[0]=="--self-test";DataDir=Testing?Path.GetFullPath(args[1]):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"StarcaseArchive");BaseUrl="http://localhost:"+(Testing?"17752":"17652");Directory.CreateDirectory(DataDir);bool created;using(var mutex=new Mutex(true,Testing?"Local\\StarcaseArchiveTest":"Local\\StarcaseArchive",out created)){if(!created){IntPtr w=FindWindow(null,"星匣 · 创作档案");if(w!=IntPtr.Zero){ShowWindow(w,9);SetForegroundWindow(w);}return;}try{StartBridge();Application.Run(new ArchiveWindow());}catch(Exception e){if(Testing)File.WriteAllText(Path.Combine(DataDir,"error.txt"),e.ToString());else{LogError("startup",e);MessageBox.Show("星匣无法启动：\n"+e.Message+"\n\n错误记录："+Path.Combine(DataDir,"startup.log"),"星匣");}}finally{if(OwnedBridge!=null)try{if(!OwnedBridge.HasExited)OwnedBridge.Kill();OwnedBridge.Dispose();}catch{}}}}
 static void StartBridge(){bool occupied=false;try{using(var client=new ShortClient()){var x=Json.Deserialize<Dictionary<string,object>>(client.DownloadString(BaseUrl+"/api/session"));if(Convert.ToString(x["app"])=="starcase-archive"&&Convert.ToString(x["version"])==UpdateProtocol.Current)return;occupied=!BridgeLifecycle24.TryStopSameFolder(BaseDir,Testing?"17752":"17652");}}catch(WebException){}if(occupied)throw new Exception("星匣端口被其它版本占用，请先关闭旧版星匣。");string python=Path.Combine(BaseDir,"runtime","python.exe"),server=Path.Combine(BaseDir,"service","server.py");if(!File.Exists(python)||!File.Exists(server))throw new Exception("缺少运行文件，请完整解压电脑版安装包。");var start=new ProcessStartInfo(python,"\""+server+"\" --port "+(Testing?"17752":"17652")+" --data-dir \""+DataDir+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=BaseDir,RedirectStandardError=true,RedirectStandardOutput=true};OwnedBridge=Process.Start(start);OwnedBridge.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)try{File.AppendAllText(Path.Combine(DataDir,"service-error.log"),e.Data+Environment.NewLine);}catch{}};OwnedBridge.BeginErrorReadLine();OwnedBridge.BeginOutputReadLine();for(int i=0;i<80;i++){if(OwnedBridge.HasExited)throw new Exception("本机资料服务启动失败，请查看 service-error.log。");try{using(var c=new ShortClient()){if(c.DownloadString(BaseUrl+"/api/session").Contains("starcase-archive"))return;}}catch{}Thread.Sleep(100);}throw new Exception("本机资料服务启动超时。");}
 internal static void LogError(string stage,Exception error){try{File.AppendAllText(Path.Combine(DataDir,"startup.log"),DateTime.UtcNow.ToString("o")+" "+stage+"\n"+error.ToString()+"\n",Encoding.UTF8);}catch{}}
 internal static void OpenExternal(string url){Uri uri;if(Uri.TryCreate(url,UriKind.Absolute,out uri)&&(uri.Scheme=="http"||uri.Scheme=="https"))Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindow(string a,string b);[DllImport("user32.dll")]static extern bool ShowWindow(IntPtr w,int n);[DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr w);
}
internal class ShortClient:WebClient{protected override WebRequest GetWebRequest(Uri address){var r=base.GetWebRequest(address);r.Timeout=800;return r;}}
internal sealed class ArchiveWindow:Form {
 WebView2 browser;Updates updates;
 internal ArchiveWindow(){Text="星匣 · 创作档案";Width=1400;Height=960;MinimumSize=new Size(960,680);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(240,232,217);try{Icon=new Icon(Path.Combine(Program.BaseDir,"starcase.ico"));}catch{}browser=new WebView2{Dock=DockStyle.Fill,DefaultBackgroundColor=BackColor};Controls.Add(browser);updates=new Updates(raw=>{if(IsHandleCreated&&!IsDisposed)try{BeginInvoke(new Action(async()=>await JS("window.onUpdate20&&onUpdate20("+raw+")")));}catch{}});Shown+=async(s,e)=>await Start();if(Program.Testing){ShowInTaskbar=false;Opacity=0;}FormClosed+=(s,e)=>{if(browser!=null)browser.Dispose();};}
 async Task JS(string code){if(browser!=null&&browser.CoreWebView2!=null)await browser.CoreWebView2.ExecuteScriptAsync(code);}
 async Task Start(){try{var env=await CoreWebView2Environment.CreateAsync(null,Path.Combine(Program.DataDir,"webview"),null);await browser.EnsureCoreWebView2Async(env);var core=browser.CoreWebView2;core.Settings.AreDevToolsEnabled=Program.Testing;core.Settings.IsStatusBarEnabled=false;core.Settings.AreDefaultContextMenusEnabled=false;await core.AddScriptToExecuteOnDocumentCreatedAsync("window.__starcaseDesktop=true");core.WebMessageReceived+=Message;core.NewWindowRequested+=(s,e)=>{e.Handled=true;Program.OpenExternal(e.Uri);};core.NavigationStarting+=(s,e)=>{if(!e.Uri.StartsWith(Program.BaseUrl+"/")&&e.Uri!="about:blank"){e.Cancel=true;if(e.IsUserInitiated)Program.OpenExternal(e.Uri);}};core.DownloadStarting+=(s,e)=>{var hold=e.GetDeferral();try{e.Handled=true;using(var dialog=new SaveFileDialog{FileName=Path.GetFileName(e.ResultFilePath),Filter="资料包与文稿|*.json;*.md;*.txt|所有文件|*.*"}){if(Program.Testing)e.ResultFilePath=Path.Combine(Program.DataDir,dialog.FileName);else if(dialog.ShowDialog(this)==DialogResult.OK)e.ResultFilePath=dialog.FileName;else e.Cancel=true;}}finally{hold.Complete();}};core.NavigationCompleted+=async(s,e)=>{if(Program.Testing)await SelfTest();};core.Navigate(Program.BaseUrl+"/index.html");}catch(Exception ex){if(Program.Testing){File.WriteAllText(Path.Combine(Program.DataDir,"error.txt"),ex.ToString());Close();}else{Program.LogError("WebView2",ex);RuntimeHelp(ex);}}}
 async void Message(object s,CoreWebView2WebMessageReceivedEventArgs ev){if(!ev.Source.StartsWith(Program.BaseUrl+"/"))return;string id="",value="";bool ok=true;try{var x=Program.Json.Deserialize<Dictionary<string,object>>(ev.WebMessageAsJson);id=Convert.ToString(x["id"]);switch(Convert.ToString(x["type"])){case "update20":value=updates.Request(x);break;case "copy":Clipboard.SetText(Convert.ToString(x["text"]));break;default:throw new Exception("不支持的操作");}}catch(Exception ex){ok=false;value=ex.Message;}await JS("hostReply("+Program.Json.Serialize(id)+","+(ok?"true":"false")+","+Program.Json.Serialize(value)+")");}
 void RuntimeHelp(Exception error){bool missing=error is WebView2RuntimeNotFoundException;Controls.Clear();var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(40),FlowDirection=FlowDirection.TopDown,WrapContents=false};panel.Controls.Add(new Label{AutoSize=true,MaximumSize=new Size(800,0),Font=new Font("Microsoft YaHei UI",13),Text=missing?"星匣需要 Microsoft Edge WebView2 Runtime。\n\n可以安装完整包附带的微软离线运行环境，或先用浏览器打开资料库。资料保存在本机应用数据目录。":"资料界面初始化失败：\n"+error.Message+"\n\n可先在浏览器打开资料库。错误记录在 "+Path.Combine(Program.DataDir,"startup.log")});var install=new Button{Text="安装随包附带的运行环境",AutoSize=true,Margin=new Padding(0,30,0,10)};install.Click+=(s,e)=>{string path=Path.Combine(Program.BaseDir,"MicrosoftEdgeWebView2RuntimeInstallerX64.exe");if(File.Exists(path))Process.Start(new ProcessStartInfo(path,"/install"){UseShellExecute=true});else Program.OpenExternal("https://developer.microsoft.com/microsoft-edge/webview2/");};if(missing)panel.Controls.Add(install);var web=new Button{Text="在浏览器打开资料库",AutoSize=true};web.Click+=(s,e)=>Program.OpenExternal(Program.BaseUrl+"/index.html");panel.Controls.Add(web);Controls.Add(panel);}
 async Task SelfTest(){try{for(int i=0;i<80;i++){string loaded=await browser.CoreWebView2.ExecuteScriptAsync("Boolean(window.ArchiveApp&&ArchiveApp.snapshot())");if(loaded=="true")break;await Task.Delay(100);}await JS("document.getElementById('captureText').value='Windows 原生保存验证';quickCapture();");await Task.Delay(800);string data=await browser.CoreWebView2.ExecuteScriptAsync("JSON.stringify({platform:nativePlatform(),count:ArchiveApp.snapshot().entries.length,found:ArchiveApp.snapshot().entries.some(e=>e.title==='Windows 原生保存验证'),server:serverAvailable})");File.WriteAllText(Path.Combine(Program.DataDir,"native-result.json"),data);await JS("openUpdates()");await Task.Delay(500);string update=await browser.CoreWebView2.ExecuteScriptAsync("JSON.stringify(updateState)");File.WriteAllText(Path.Combine(Program.DataDir,"update-result.json"),update);using(var image=File.Create(Path.Combine(Program.DataDir,"native-preview.png")))await browser.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,image);File.WriteAllText(Path.Combine(Program.DataDir,"success.txt"),"Native WebView2, save and update bridge passed");}catch(Exception ex){File.WriteAllText(Path.Combine(Program.DataDir,"error.txt"),ex.ToString());}finally{Close();}}
}
